package cn.sixnine.filmlog;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Native callback/lifecycle checks with a synthetic snapshot; no optical camera claim. */
public final class ReferenceSaveInstrumentation extends Instrumentation {
 public static final class Host extends Activity{static volatile Intent answer;static volatile int code;@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);code=result;answer=data;}}
 interface Action{void run()throws Exception;}Activity host,meter;int assertions;JSONArray timings=new JSONArray();Context context;
 void check(boolean ok,String s){assertions++;if(!ok)throw new AssertionError(s);}void main(Action a)throws Exception{Throwable[] fail={null};runOnMainSync(()->{try{a.run();}catch(Throwable t){fail[0]=t;}});waitForIdleSync();if(fail[0]!=null)throw new RuntimeException(fail[0]);}
 Object field(String n)throws Exception{java.lang.reflect.Field f=MeterActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(meter);}void call(String n,Class<?>[]types,Object...args)throws Exception{java.lang.reflect.Method m=MeterActivity.class.getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(meter,args);}
 Bitmap snapshot(){Bitmap b=Bitmap.createBitmap(1280,1280,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint();for(int y=0;y<1280;y+=10){p.setColor(0xff000000|(y*137));c.drawRect(0,y,1280,y+10,p);}return b;}
 void open()throws Exception{if(meter!=null&&!meter.isDestroyed()){main(()->meter.finish());for(int i=0;i<60&&!meter.isDestroyed();i++)SystemClock.sleep(30);}Host.answer=null;Host.code=0;ActivityMonitor monitor=addMonitor(MeterActivity.class.getName(),null,false);main(()->host.startActivityForResult(new Intent(host,MeterActivity.class).putExtra("record_now",true).putExtra("return_exposure",true),77));meter=monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(meter!=null,"meter started");waitForIdleSync();}
 void awaitRecycled(Bitmap image)throws Exception{for(int i=0;i<200&&!image.isRecycled();i++)SystemClock.sleep(20);check(image.isRecycled(),"snapshot released");waitForIdleSync();}
 void awaitAnswer()throws Exception{for(int i=0;i<200&&Host.answer==null;i++)SystemClock.sleep(20);check(Host.code==Activity.RESULT_OK&&Host.answer!=null,"result only after persistence");}
 Intent answer(String token,long tap){return new Intent().putExtra("record_meter",true).putExtra("reference_token",token).putExtra("record_tap",tap).putExtra("record_elapsed",1234L).putExtra("record_delta",-10).putExtra("record_zone",480).putExtra("aperture","8").putExtra("shutter","1/125");}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();String previous=Workspace.current(getTargetContext());boolean ok=false;try{check(getTargetContext().getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolation");Workspace.activate(getTargetContext(),UUID.randomUUID().toString());context=Workspace.context(getTargetContext());host=startActivitySync(new Intent(getTargetContext(),Host.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
 for(int i=0;i<3;i++){open();String token=UUID.randomUUID().toString(),expected=UUID.randomUUID().toString();Bitmap image=snapshot(),copy=image.copy(Bitmap.Config.ARGB_8888,false);ReferencePhotos.capture(context,expected,copy);copy.recycle();long tap=System.currentTimeMillis()-100;double[] spent={0};long start=System.nanoTime();main(()->{long began=System.nanoTime();call("saveReference",new Class<?>[]{Intent.class,String.class,Bitmap.class},answer(token,tap),token,image);spent[0]=(System.nanoTime()-began)/1e6;check((Boolean)field("sending")&&!((Button)field("saveControl")).isEnabled(),"saving state visible and duplicate tap disabled");call("useReading",new Class<?>[]{});});awaitRecycled(image);awaitAnswer();timings.put(new JSONObject().put("enqueue_main_ms",spent[0]).put("complete_wall_ms",(System.nanoTime()-start)/1e6));Intent result=Host.answer;check(result.getLongExtra("record_tap",0)==tap&&result.getLongExtra("record_elapsed",0)==1234&&result.getIntExtra("record_delta",0)==-10&&result.getIntExtra("record_zone",0)==480,"original tap monotonic clock offset zone retained");check(result.getStringExtra("aperture").equals("8")&&result.getStringExtra("shutter").equals("1/125"),"meter values preserved");check(Arrays.equals(java.nio.file.Files.readAllBytes(ReferencePhotos.draft(context,expected).toPath()),java.nio.file.Files.readAllBytes(ReferencePhotos.draft(context,token).toPath())),"same JPEG90 pixels and bytes");ReferencePhotos.discard(context,expected);ReferencePhotos.discard(context,token);}
 open();String cancelled=UUID.randomUUID().toString();Bitmap abandoned=snapshot();main(()->{call("saveReference",new Class<?>[]{Intent.class,String.class,Bitmap.class},answer(cancelled,System.currentTimeMillis()),cancelled,abandoned);meter.finish();});awaitRecycled(abandoned);for(int i=0;i<60&&!meter.isDestroyed();i++)SystemClock.sleep(30);main(()->{});check(Host.code!=Activity.RESULT_OK&&!ReferencePhotos.draft(context,cancelled).exists(),"leaving during write yields no result or orphan");
 open();String failed=UUID.randomUUID().toString();File blocked=new File(ReferencePhotos.draft(context,failed)+".part");check(blocked.mkdir(),"failure fixture");new File(blocked,"block").createNewFile();Bitmap broken=snapshot();main(()->call("saveReference",new Class<?>[]{Intent.class,String.class,Bitmap.class},answer(failed,System.currentTimeMillis()),failed,broken));awaitRecycled(broken);for(int i=0;i<100;i++){boolean[] busy={true};main(()->busy[0]=(Boolean)field("sending"));if(!busy[0])break;SystemClock.sleep(20);}main(()->{check(!(Boolean)field("sending")&&((Button)field("saveControl")).getText().toString().equals("保存曝光"),"IO failure exits saving; fresh-reading gate still applies");check(!meter.isFinishing()&&Host.answer==null,"failed IO never returns successful exposure");});new File(blocked,"block").delete();blocked.delete();Bitmap retry=snapshot();main(()->call("saveReference",new Class<?>[]{Intent.class,String.class,Bitmap.class},answer(failed,System.currentTimeMillis()),failed,retry));awaitRecycled(retry);awaitAnswer();ReferencePhotos.discard(context,failed);
 try(Writer writer=new FileWriter(new File(getTargetContext().getFilesDir(),"reference-save-perf.json"))){writer.write(timings.toString(2));}out.putString("stream","PASS "+assertions+" assertions: asynchronous JPEG90, native result success after fsync, identical JPEG bytes, original tap/elapsed/offset/zone/settings; visible saving/duplicate tap; leaving cleanup; actual file IO failure and retry. "+timings+"\n");ok=true;
 }catch(Throwable t){out.putString("stream",android.util.Log.getStackTraceString(t));}finally{try{if(meter!=null)main(()->meter.finish());if(host!=null)main(()->host.finish());Workspace.activate(getTargetContext(),previous);}catch(Exception ignored){}}finish(ok?-1:0,out);}
}
